	-- count of running data profile delete batch jobs is > 1 for past 24 hours
	select @runDataProfileDeleteCount = count(1) from api.execution e inner join api.ExecutionDeleteAssetDataProfile ea on e.ExecutionID = ea.ExecutionID where e.completedOn is null and e.startedon > DATEADD(day, -1, GETDATE()) and e.ErrorMessage is null

	if ( @runDataProfileDeleteCount > 1 )
