	select @runRelationshipCount = count(1) from api.execution e inner join api.ExecutionRelationship ea on e.ExecutionID = ea.ExecutionID where e.completedOn is null and e.startedon > DATEADD(day, -1, GETDATE())  and e.ErrorMessage is null

	if ( @runRelationshipCount > 1 )
	begin
		return 0;
	end

	-- count of running asset delete batch jobs is > 1 for past 24 hours
	select @runAssetTypeDeleteCount = count(1) from api.execution e inner join api.executiondeletedassettype ea on e.ExecutionID = ea.ExecutionID where e.completedOn is null and e.startedon > DATEADD(day, -1, GETDATE())  and e.ErrorMessage is null

	if ( @runAssetTypeDeleteCount > 1 )
	begin
		return 0;
	end



	-- some combination of the 3 types of batch jobs running more than 1 instance already
	if ((@runAssetCount + @runAssetDeleteCount + @runRelationshipCount + @runAssetTypeDeleteCount + @runDataProfileDeleteCount + @runDataProfileCount) > 1)
	begin
		return 0;
	end

	--all other checks have passed. make sure there are no other jobs with the same asset/intersect type running
	if (@executionID is not null)
	begin

		--don't consider any execution older than 24 hrs
		if exists (select 1 from api.Execution where ExecutionID = @executionID and StartedOn < DATEADD(day, -1, GETDATE()))
